) => {
    if (signal.aborted) {
        return Promise.resolve();
    }

    const tab = window.open(ApprovalURL);

    return new Promise<void>((resolve, reject) => {
        let finished = false;
        let timeoutId: number | undefined;

        const cleanup = () => {
            if (timeoutId !== undefined) {
                window.clearTimeout(timeoutId);
                timeoutId = undefined;
            }
            // eslint-disable-next-line @typescript-eslint/no-use-before-define
            window.removeEventListener('message', onMessage, false);
            // eslint-disable-next-line @typescript-eslint/no-use-before-define
            signal.removeEventListener('abort', abort);
        };

        const finish = () => {
            if (finished) {
                return;
            }
            finished = true;
            cleanup();
            tab?.close();
            resolve();
        };

        const fail = (error: unknown) => {
            if (finished) {
                return;
            }
            finished = true;
            cleanup();
            tab?.close();
            reject(error);
        };

        const poll = async () => {
            if (finished) {
                return;
            }
            if (signal.aborted || tab?.closed) {
                finish();
                return;
            }

            try {
                const { Status } = await api({ ...getTokenStatus(Token), signal });
                if (finished) {
                    return;
                }
                if (signal.aborted || Status !== STATUS_PENDING) {
                    if (
                        Status === STATUS_CHARGEABLE ||
                        Status === STATUS_FAILED ||
                        Status === STATUS_CONSUMED ||
                        Status === STATUS_NOT_SUPPORTED
                    ) {
                        finish();
                        return;
                    }
                    if (signal.aborted) {
                        finish();
                        return;
                    }
                    fail(new Error(c('Error').t`Unknown payment token status`));
                    return;
                }
                timeoutId = window.setTimeout(poll, pollingInterval);
            } catch (error) {
                if (signal.aborted) {
                    finish();
                    return;
                }
                fail(error);
            }
        };

        const onMessage = (event: MessageEvent) => {
            if (getHostname(event.origin) !== ReturnHost) {
                return;
            }

            const { cancel } = event.data || {};
            if (cancel === '1') {
                finish();
                return;
            }

            if (timeoutId !== undefined) {
                window.clearTimeout(timeoutId);
                timeoutId = undefined;
            }
            void poll();
        };

        const abort = () => finish();

        signal.addEventListener('abort', abort);
        window.addEventListener('message', onMessage, false);
        void poll();
    });
};

